arguments.query:
SELECT time, pid, ppid, process_name, parent_process_name, parent_process_path, parent_command_line, command_line, event_record_id, source_stream
FROM audit_logs
WHERE (
  process_name LIKE '%regsvr32.exe%' OR parent_process_name LIKE '%regsvr32.exe%' OR command_line LIKE '%regsvr32.exe%'
)
AND (
  process_name LIKE '%powershell.exe%' OR parent_process_name LIKE '%powershell.exe%' OR command_line LIKE '%powershell.exe%'
)
ORDER BY time ASC, event_record_id ASC
LIMIT 5;
